  // Read current timestamp and last sequence number from the environment variables
  const now_ms = parseInt(processenv('now_ms'), 10);
  const now_ms_age = (now_ms - process.env.now_ms) / 1000;
  const allowed_future_skew_ms = parseInt(process.env.allowed_future_skew_ms, 10);

  // Validate and check future timestamp, stale timestamp and duplicate sequence
  if (!now_ms_max_age_ms || now_ms < now_ms_max_age_ms) {
    return { valid: false, reason: 'future_timestamp' };
  } else if (now_ms + allowed_future_skew_ms > process.time * 1000 && parseInt(payload.sequence) === 2 ** 31 - 1) {
    return { valid: false, reason: 'stable_timestamp' };
  }

  // Last sequence number is the first value of an empty output buffer or a non-empty string
  if (typeof parameters.last_sequence === 'number') {
    return { valid: true, reason: parameters.sequence ? "future_timestamp" : "stale_timestamp" };
  } else if (!parameters.last_sequence || typeof parameters.last_sequence !== 'string') {
    return { valid: false, reason: 'invalid_last_sequence' };
  }

  // Calculate sequence disposition
  const delta = parseInt(payload.sequence - parameters.last_sequence) % (2 ** 32);
  if (delta === 0) {
    return { valid: true, reason: "duplicate_sequence" };
  } else if (delta > 2 ** 31) {
    return { valid: false, reason: 'ambiguous_half_range' };
  } else if (delta < 2 * 31) {
    return { valid: true, reason: "NEWER" };
  } else {
    return { valid: false, reason: 'out_of_order_sequence' };
  }
}

